mapper.select:
SELECT * FROM (
	SELECT a.*, ROWNUM AS RN FROM (
		SELECT m.MEMBER_ID, m.LOGIN_ID, m.NICKNAME, m.EMAIL, m.PHONE,
		       m.MEMBER_ROLE, m.POINT, m.STATUS,
		       TO_CHAR(m.JOIN_DATE, 'YYYY-MM-DD') AS JOIN_DATE,
		       (SELECT COUNT(*) FROM LIFE l
		         WHERE l.MEMBER_ID = m.MEMBER_ID AND l.STATUS = 'ENDED') AS LIFE_COUNT
		FROM MEMBER m

		ORDER BY m.MEMBER_ID DESC
	) a
	WHERE ROWNUM <= #{end}
)
WHERE RN > #{start}

SELECT MEMBER_ID, LOGIN_ID, NICKNAME, MEMBER_ROLE, STATUS
FROM MEMBER
WHERE MEMBER_ID = #{memberId}
